function(props) {
  // Main component function
  function GoogleCalendarEventCard(props) {
    const event = props.data;
    if (!event) return null;

    // Function to generate color from string
    function stringToColor(string) {
      let hash = 0;
      for (let i = 0; i < string.length; i++) {
        hash = string.charCodeAt(i) + ((hash << 5) - hash);
      }
      let color = '#';
      for (let i = 0; i < 3; i++) {
        const value = (hash >> (i * 8)) & 0xFF;
        color += ('00' + value.toString(16)).substr(-2);
      }
      return color;
    }

    // Format response status
    function formatResponseStatus(status) {
      if (!status) return '';

      switch(status.toLowerCase()) {
        case 'accepted':
          return 'Accepted';
        case 'declined':
          return 'Declined';
        case 'tentative':
          return 'Maybe';
        case 'needsaction':
          return 'Pending';
        default:
          return status;
      }
    }

    // User avatar component with tooltip
    function UserAvatar({ user, index }) {
      const name = user.displayName || user.email || '';
      const initials = name.split(' ')
        .map((part) => part.charAt(0))
        .join('')
        .substring(0, 2)
        .toUpperCase();

      const backgroundColor = stringToColor(name);
      const status = formatResponseStatus(user.responseStatus);

      const avatarStyle = {
        width: '20px',
        height: '20px',
        borderRadius: '50%',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        color: 'white',
        fontSize: '10px',
        fontWeight: '500',
        backgroundColor: backgroundColor,
        position: 'relative',
        cursor: 'pointer',
        border: '1px solid white',
        zIndex: 5 - index // Higher index = lower z-index to stack properly
      };

      const tooltipContainerStyle = {
        position: 'relative',
        zIndex: 0,
        marginLeft: index > 0 ? '-8px' : '0' // Overlap avatars by 8px
      };

      // Using onMouseOver/onMouseOut for tooltip functionality
      return React.createElement('div', {
        style: tooltipContainerStyle,
        className: 'user-avatar-container',
        onMouseOver: function(e) {
          const tooltip = document.createElement('div');
          tooltip.className = 'avatar-tooltip';
          tooltip.style.position = 'absolute';
          tooltip.style.bottom = '100%';
          tooltip.style.left = '50%';
          tooltip.style.transform = 'translateX(-50%)';
          tooltip.style.marginBottom = '6px';
          tooltip.style.padding = '4px 8px';
          tooltip.style.backgroundColor = '#333';
          tooltip.style.color = 'white';
          tooltip.style.borderRadius = '4px';
          tooltip.style.fontSize = '10px';
          tooltip.style.whiteSpace = 'nowrap';
          tooltip.style.zIndex = '10';

          const nameElement = document.createElement('div');
          nameElement.style.fontWeight = '500';
          nameElement.textContent = name;
          tooltip.appendChild(nameElement);

          if (status) {
            const statusElement = document.createElement('div');
            statusElement.style.color = '#ccc';
            statusElement.textContent = status;
            tooltip.appendChild(statusElement);
          }

          // Add arrow
          const arrow = document.createElement('div');
          arrow.style.position = 'absolute';
          arrow.style.top = '100%';
          arrow.style.left = '50%';
          arrow.style.transform = 'translateX(-50%)';
          arrow.style.borderWidth = '4px';
          arrow.style.borderStyle = 'solid';
          arrow.style.borderColor = '#333 transparent transparent transparent';
          tooltip.appendChild(arrow);

          e.currentTarget.appendChild(tooltip);
        },
        onMouseOut: function(e) {
          const tooltip = e.currentTarget.querySelector('.avatar-tooltip');
          if (tooltip) {
            tooltip.remove();
          }
        }
      }, React.createElement('div', {
        style: avatarStyle
      }, initials));
    }

    // Component for additional attendees
    function MoreAttendees({ count, index }) {
      const style = {
        width: '20px',
        height: '20px',
        borderRadius: '50%',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        backgroundColor: '#e2e8f0',
        color: '#64748b',
        fontSize: '10px',
        fontWeight: '500',
        border: '1px solid white',
        zIndex: 1
      };

      return React.createElement('div', {
        style: {
          position: 'relative',
          zIndex: 0,
          marginLeft: '-8px' // Overlap with the last avatar
        }
      }, React.createElement('div', {
        style: style
      }, '+' + count));
    }

    const formatTime = (dateStr) => {
      if (!dateStr) return 'TBD';
      const date = new Date(dateStr);
      if (date.toString() === 'Invalid Date') return 'TBD';
      return date.toLocaleTimeString('en-US', {
        hour: 'numeric',
        minute: '2-digit',
        hour12: true,
        timeZone: 'America/Los_Angeles'
      }).replace(/\s/g, '');
    };

    // Short date format (Feb 28)
    const formatShortDate = (dateStr) => {
      if (!dateStr) return '';
      const date = new Date(dateStr);
      if (date.toString() === 'Invalid Date') return '';
      return date.toLocaleDateString('en-US', {
        month: 'short',
        day: 'numeric'
      });
    };

    const startTime = formatTime(event.start);
    const endTime = formatTime(event.end);
    const shortDate = formatShortDate(event.start);

    // Link icon SVG
    function LinkIcon() {
      return React.createElement('svg', {
        width: '10',
        height: '10',
        viewBox: '0 0 16 16',
        fill: 'none',
        style: { color: '#64748b' }
      }, [
        React.createElement('path', {
          key: 'p1',
          d: 'M6.5 9.5L9.5 6.5',
          stroke: 'currentColor',
          strokeWidth: '1.5',
          strokeLinecap: 'round',
          strokeLinejoin: 'round'
        }),
        React.createElement('path', {
          key: 'p2',
          d: 'M4.5 7.5L3 9C2.17157 9.82843 2.17157 11.1716 3 12C3.82843 12.8284 5.17157 12.8284 6 12L7.5 10.5',
          stroke: 'currentColor',
          strokeWidth: '1.5',
          strokeLinecap: 'round',
          strokeLinejoin: 'round'
        }),
        React.createElement('path', {
          key: 'p3',
          d: 'M8.5 5.5L10 4C10.8284 3.17157 12.1716 3.17157 13 4C13.8284 4.82843 13.8284 6.17157 13 7L11.5 8.5',
          stroke: 'currentColor',
          strokeWidth: '1.5',
          strokeLinecap: 'round',
          strokeLinejoin: 'round'
        })
      ]);
    }

    const cardStyle = {
      position: 'relative',
      borderRadius: '8px',
      border: '1px solid #e2e8f0',
      backgroundColor: '#ffffff',
      padding: '8px 12px',
      marginBottom: '8px',
      width: '100%',
      boxSizing: 'border-box'
    };

    const flexContainerStyle = {
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'space-between',
      gap: '8px'
    };

    const contentStyle = {
      minWidth: 0,
      flex: 1
    };

    const titleContainerStyle = {
      display: 'flex',
      alignItems: 'center',
      gap: '2px'
    };

    const titleStyle = {
      fontWeight: '500',
      color: '#1e293b',
      overflow: 'hidden',
      textOverflow: 'ellipsis',
      whiteSpace: 'nowrap',
      fontSize: '14px',
      margin: 0
    };

    const timeStyle = {
      fontSize: '12px',
      color: '#64748b',
      overflow: 'hidden',
      textOverflow: 'ellipsis',
      whiteSpace: 'nowrap',
      marginTop: '4px',
      margin: 0
    };

    const attendeesStyle = {
      display: 'flex',
      alignItems: 'center'
    };

    const linkStyle = {
      color: '#64748b',
      display: 'flex',
      alignItems: 'center',
      marginRight: '4px',
      textDecoration: 'none',
      flexShrink: 0
    };

    return React.createElement('div', { style: cardStyle },
      React.createElement('div', { style: flexContainerStyle },
        React.createElement('div', { style: contentStyle },
          React.createElement('div', { style: titleContainerStyle },
            event.htmlLink && React.createElement('a', {
              href: event.htmlLink,
              target: '_blank',
              rel: 'noopener noreferrer',
              style: linkStyle
            }, React.createElement(LinkIcon)),
            React.createElement('h3', { style: titleStyle }, event.summary)
          ),
          React.createElement('p', { style: timeStyle },
            shortDate + ', ' + startTime + ' - ' + endTime
          )
        ),
        React.createElement('div', { style: attendeesStyle },
          event.attendees && event.attendees.slice(0, 3).map((attendee, index) =>
            React.createElement(UserAvatar, { key: index, user: attendee, index: index })
          ),
          event.attendees && event.attendees.length > 3 &&
            React.createElement(MoreAttendees, { count: event.attendees.length - 3, index: 3 })
        )
      )
    );
  }

  // Render multiple events if provided
  function renderEvents(props) {
    const events = Array.isArray(props.data) ? props.data : [props.data];

    const containerStyle = {
      display: 'flex',
      flexWrap: 'wrap',
      gap: '12px',
      width: '100%'
    };

    const cardWrapperStyle = {
      width: 'calc(50% - 6px)', // Two cards per row with gap in between
      minWidth: '250px',
      boxSizing: 'border-box'
    };

    return React.createElement('div', { style: containerStyle },
      events.map((event, index) => 
        React.createElement('div', { 
          key: event.id || index,
          style: cardWrapperStyle
        },
          React.createElement(GoogleCalendarEventCard, { 
            data: event 
          })
        )
      )
    );
  }

  // Return the appropriate component based on input
  return Array.isArray(props.data) ? renderEvents(props) : GoogleCalendarEventCard(props);
}
